  "node_modules/fluxkit/vec.d.ts": "/**\n * Vectors and rotations for model functions. Each helper is ordinary\n * JavaScript, which is what runs on the CPU, and has a WGSL twin the compiler\n * emits for the GPU. Vectors are `[x, y, z]` arrays; a rotation is a unit\n * quaternion `[w, x, y, z]` (scalar first, Ramtal & Dobre, 2014).\n *\n * JavaScript has no operator overloading, so `a + b` on two vectors is not a\n * vector sum: use `add(a, b)`, `sub`, `scale` and friends. The compiler says\n * so if you try.\n */\nexport type Vec3 = readonly [number, number, number];\nexport type Quat = readonly [number, number, number, number];\n/** A vector. */\nexport declare const vec: (x: number, y: number, z: number) => Vec3;\nexport declare const add: (a: Vec3, b: Vec3) => Vec3;\nexport declare const sub: (a: Vec3, b: Vec3) => Vec3;\n/** a · k */\nexport declare const scale: (a: Vec3, k: number) => Vec3;\nexport declare const dot: (a: Vec3, b: Vec3) => number;\nexport declare const cross: (a: Vec3, b: Vec3) => Vec3;\nexport declare const length: (a: Vec3) => number;\nexport declare const normalize: (a: Vec3) => Vec3;\n/** Hamilton product of two quaternions. */\nexport declare const qmul: (a: Quat, b: Quat) => Quat;\n/** Rotates a vector by a rotation: q ⊗ (0, v) ⊗ q*. */\nexport declare const rotate: (q: Quat, v: Vec3) => Vec3;\n/**\n * The rate of a rotation: its angular velocity (rad per unit time, in the\n * body's frame). Return it for a `rotation()` state in `rates`.\n */\nexport declare function spin(x: number, y: number, z: number): Vec3;\nexport declare function spin(omega: Vec3): Vec3;\n/** The angle of a rotation, radians in [0, 2π). */\nexport declare const angle: (q: Quat) => number;\n/** dq/dt = ½ q ⊗ (0, ω): how a rotation's quaternion changes. */\nexport declare const quatRate: (q: Quat, w: Vec3) => Quat;\n/** The rotation by `radians` about `axis` (normalised for you). */\nexport declare function axisAngle(axis: Vec3, radians: number): Quat;\n/** WGSL for the helpers, emitted once into every kernel. */\nexport declare const HELPERS_WGSL = \"\\nfn fk_qmul(a: vec4<f32>, b: vec4<f32>) -> vec4<f32> {\\n  return vec4<f32>(\\n    a.x * b.x - a.y * b.y - a.z * b.z - a.w * b.w,\\n    a.x * b.y + a.y * b.x + a.z * b.w - a.w * b.z,\\n    a.x * b.z - a.y * b.w + a.z * b.x + a.w * b.y,\\n    a.x * b.w + a.y * b.z - a.z * b.y + a.w * b.x\\n  );\\n}\\nfn fk_rotate(q: vec4<f32>, v: vec3<f32>) -> vec3<f32> {\\n  return fk_qmul(fk_qmul(q, vec4<f32>(0.0, v)), vec4<f32>(q.x, -q.yzw)).yzw;\\n}\\nfn fk_quat_rate(q: vec4<f32>, w: vec3<f32>) -> vec4<f32> {\\n  return 0.5 * fk_qmul(q, vec4<f32>(0.0, w));\\n}\\nfn fk_angle(q: vec4<f32>) -> f32 {\\n  return 2.0 * atan2(length(q.yzw), q.x);\\n}\\nfn fk_round(x: f32) -> f32 {\\n  return floor(x + 0.5); // Math.round: halves round up (WGSL's round goes to even)\\n}\\nfn fk_cbrt(x: f32) -> f32 {\\n  return sign(x) * pow(abs(x), 1.0 / 3.0);\\n}\\n\";\n"
